/**
 * Generates apps/obsidian/remix-skin/generated.ts from the checked-in map and
 * the authentic remixicon@4.8.0 line SVGs in apps/obsidian/remix-skin/icons.
 *
 * The generated file is committed so a clean checkout builds without a network
 * fetch or a remixicon dependency. tests/remix-skin.test.ts regenerates the
 * table in memory and fails if the committed file drifts from its sources.
 *
 *   node scripts/build-remix-skin.mjs
 */
import { readFile, writeFile, readdir } from 'node:fs/promises'
import { resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const dir = resolve(root, 'apps/obsidian/remix-skin')
const out = resolve(dir, 'generated.ts')

/** Remix ships the root presentation attributes on <svg>; the body alone loses the fill. */
function bodyOf(svg) {
  const open = svg.indexOf('>')
  const close = svg.lastIndexOf('</svg>')
  if (open < 0 || close < 0) throw new Error('not an svg document')
  return svg.slice(open + 1, close).trim()
}

const map = JSON.parse(await readFile(resolve(dir, 'map.json'), 'utf8'))
const files = new Set((await readdir(resolve(dir, 'icons'))).map((n) => n.replace(/\.svg$/, '')))
const targets = [...new Set(Object.values(map.resolved))].sort()
const unused = [...files].filter((n) => !targets.includes(n))
if (unused.length) throw new Error(`icons/ holds files no mapping reaches: ${unused.join(', ')}`)

const entries = []
for (const name of targets) {
  const svg = await readFile(resolve(dir, 'icons', `${name}.svg`), 'utf8')
  entries.push(`  ${JSON.stringify(name)}: ${JSON.stringify(bodyOf(svg))},`)
}

const source = `// GENERATED by scripts/build-remix-skin.mjs — do not hand-edit.
// Sources: apps/obsidian/remix-skin/map.json and apps/obsidian/remix-skin/icons/*.svg,
// extracted from remixicon@4.8.0 (Apache-2.0, REMIX-LICENSE.txt).
// Each value is the inner markup of a 24x24 line icon whose root element sets
// fill="currentColor", so the host must supply that fill on the <svg> it injects into.

/** Remix line-icon bodies keyed by their remixicon name. */
export const REMIX_ICON_BODIES: Record<string, string> = {
${entries.join('\n')}
}

/** Obsidian Lucide class name -> remixicon name. Absent names keep their native glyph. */
export const LUCIDE_TO_REMIX: Record<string, string> = ${JSON.stringify(
  Object.fromEntries(Object.entries(map.resolved).sort(([a], [b]) => (a < b ? -1 : 1))),
  null,
  1,
)}
`

await writeFile(out, source)
console.log(
  `generated.ts: ${Object.keys(map.resolved).length} mappings, ${targets.length} icons, ${source.length} bytes`,
)
